using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Windows;
using System.Windows.Interop;

namespace AkilliKisayol {
 public static class TouchpadTests {
  static List<GesturePoint> L(){var points=new List<GesturePoint>();for(int i=0;i<=24;i++)points.Add(new GesturePoint(0,i*8));for(int i=1;i<=24;i++)points.Add(new GesturePoint(i*8,192));return points;}
  static List<GesturePoint> Circle(double start=0,bool reverse=false){return Enumerable.Range(0,97).Select(i=>{double angle=start+(reverse?-1:1)*i*Math.PI*2/96;return new GesturePoint(Math.Cos(angle)*120,Math.Sin(angle)*120);}).ToList();}
  static Binding Shape(string name,IList<GesturePoint> points){return new Binding{Name=name,Key=0,Kind="Send key",SendKey=67,SendMods=2,Gesture=new ShapeTemplate{Points=points.Select(p=>new GesturePoint(p.X,p.Y)).ToList()}};}
  public static void Unit(Action<bool,string> check){
   var l=L();var circle=Circle();var binding=Shape("Letter L",l);check(Rules.Validate(binding,new Binding[0])==null&&binding.Combo=="Shape: Letter L","Shape trigger validates without any keyboard activation key");check(Rules.Resolve(new[]{binding},0,0,"")==null,"Shape binding never resolves as a keyboard trigger");
   check(ShapeRecognition.Similarity(l,l)>0.999,"Recorded shape matches itself");var transformed=l.Select(p=>new GesturePoint(p.X*3.4+500,p.Y*3.4-1200)).ToList();check(ShapeRecognition.Similarity(l,transformed)>0.999,"Shape recognition is translation and scale independent");check(ShapeRecognition.Similarity(circle,Circle(1.2,true))>0.9,"Closed shape accepts a different start point and drawing direction");check(ShapeRecognition.Similarity(l,circle)<0.7,"Distinct shapes are separated");var reversed=l.AsEnumerable().Reverse().ToList();check(ShapeRecognition.Similarity(l,reversed)<0.6,"Open shape direction is preserved");
   var options=new GestureOptions();check(ShapeRecognition.Match(transformed,new[]{binding},options).Binding==binding,"Confident saved shape is selected");var duplicate=binding.Copy();duplicate.Id="duplicate";check(ShapeRecognition.Match(l,new[]{binding,duplicate},options).Binding==null,"Ambiguous shape does not execute either shortcut");check(Rules.Conflicts(binding,new[]{duplicate}).Any(s=>s.StartsWith("CONFLICT")),"Duplicate shape is detected before saving");check(ShortcutConflicts.Find(new[]{binding,duplicate},new SystemShortcut[0],false).Any(c=>c.Severity=="CONFLICT"),"Shape conflicts appear in the shared conflict report");duplicate.ProfileId="game";binding.ProfileId="work";check(Rules.Conflicts(binding,new[]{duplicate}).Count==0,"Separate profiles can reuse a shape");
   check(ShapeRecognition.Match(new[]{new GesturePoint(0,0),new GesturePoint(1,1)},new[]{binding},options).Binding==null,"Tiny pointer movement cannot trigger a shortcut");var invalid=Shape("Invalid",l);invalid.Gesture.Points[0].X=double.NaN;check(Rules.Validate(invalid,new Binding[0])!=null,"Non-finite shape coordinates are rejected");check(ShapeRecognition.Normalize(new[]{new GesturePoint(2,2),new GesturePoint(2,2)}).Count==0,"Stationary input does not divide by zero");
   foreach(string key in new[]{"VolumeUp","MediaPlayPause","BrowserBack","Oem102","F24","NumPad9","PrintScreen"}){TriggerSpec parsed;check(TriggerSpec.TryParse("Ctrl+"+key,out parsed)&&TriggerSpec.FindInPrompt("When I press Ctrl+"+key+", copy text")==parsed.Text,"Extended Windows key is accepted: "+key);}
   string noTrigger=LocalLlm.Json().Serialize(new{status="ready",name="Copy",trigger="",app_id="global",message="",notes=new string[0],steps=new[]{new{kind="copy",combo="",text="",ms=0}}});var missing=LlmProtocol.ReadPlan(noTrigger,new LlmRequest{Prompt="Copy the selected text.",Applications=new List<string>()});check(!missing.Ready&&!missing.ModelProposedReady&&missing.Errors.Any(e=>e.Contains("trigger")),"Missing activation key becomes a clear question instead of an inference error");
   string folder=Path.Combine(Path.GetTempPath(),"TouchpadTests-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{
    var state=new State{AllowRemappedInput=true};state.Gestures.Device="calibrated-device";state.Gestures.PauseMilliseconds=800;state.Bindings.Add(Shape("Letter L",l));string file=Path.Combine(folder,"settings.json");Storage.Write(state,file);var read=Storage.Read(file);check(read.Bindings.Single().Gesture.Points.Count==l.Count&&read.Gestures.Device=="calibrated-device"&&read.Gestures.Enabled&&read.AllowRemappedInput,"Continuous gesture settings and templates survive persistence");var clone=read.Bindings[0].Copy();clone.Gesture.Points[0].X=900;check(read.Bindings[0].Gesture.Points[0].X==0,"Editing a shape never mutates the saved template");
    var imported=Transfer.Import(new State(),read,new Dictionary<string,string>(),true);check(imported.State.Bindings.Single().Gesture!=null&&imported.State.Gestures.PauseMilliseconds==800,"Shape templates and continuous settings transfer to another installation");
    File.WriteAllText(file,"{\"Bindings\":[{\"Id\":\"legacy\",\"Name\":\"Keep user text\",\"AppPath\":\"\",\"Target\":\"\",\"Kind\":\"\u0130\u015flem dizisi\",\"Key\":119,\"Steps\":[{\"Kind\":\"Tu\u015f\",\"Key\":67,\"Mods\":2,\"Text\":\"\",\"Delay\":0}]}],\"History\":[],\"Profiles\":[{\"Id\":\"work\",\"Name\":\"\u0130\u015f\"}],\"ActiveProfileId\":\"work\"}");read=Storage.Read(file);check(read.Bindings[0].Kind=="Workflow"&&read.Bindings[0].Steps[0].Kind=="Key"&&read.Profiles[0].Name=="Work"&&read.Bindings[0].Name=="Keep user text","Turkish legacy action identifiers migrate without translating user text");
    string app=System.Reflection.Assembly.GetExecutingAssembly().Location;File.WriteAllText(file,LocalLlm.Json().Serialize(new{Bindings=new[]{new{Id="old-launch",Name="Old launcher",AppPath="",Target=app,Kind="Uygulama",Key=119}},History=new object[0]}));read=Storage.Read(file);check(read.ApplicationPaths.Contains(app)&&read.Bindings[0].Kind=="Application","Legacy launch applications migrate before rebuilding an old application library");
   }finally{foreach(string file in Directory.GetFiles(folder))File.Delete(file);Directory.Delete(folder);}
  }
  static void Feed(GestureEngine gestures,IList<GesturePoint> points,IntPtr target){for(int i=1;i<points.Count;i++)gestures.PointForTest(points[i].X-points[i-1].X,points[i].Y-points[i-1].Y,target);gestures.Finish(true);}
  public static void Ui(MainWindow owner,KeyboardEngine unused,Action<bool,string> check,Action<Window,string> screenshot){
   owner.ProductViewForTest("Touchpad gestures");screenshot(owner,"touchpad-page-preview.png");IntPtr target=new WindowInteropHelper(owner).Handle;Native.ActivateWindow(target);
   var state=new State();var binding=Shape("Letter L",L());state.Bindings.Add(binding);using(var keyboard=new KeyboardEngine())using(var gestures=new GestureEngine(keyboard,()=>state,()=>Profiles.Effective(state),false)){
    gestures.AllowOwnWindowForTest=true;keyboard.Bindings=()=>Profiles.Effective(state);int fires=0;string selected="";keyboard.Fire=(b,w)=>{fires++;selected=b.Name;};Feed(gestures,L(),target);keyboard.FlushForTest();check(fires==1&&selected=="Letter L","Continuous shape runs after a pause with no key or button");
    state.Gestures.Enabled=false;Feed(gestures,L(),target);keyboard.FlushForTest();check(fires==1,"Disabled continuous recognition cannot run a shape");state.Gestures.Enabled=true;gestures.Refresh();keyboard.Paused=true;Feed(gestures,L(),target);keyboard.FlushForTest();check(fires==1,"Paused shortcut motor stops touchpad shapes");keyboard.Paused=false;
    keyboard.Handle(new Native.Keyboard{vk=162});Feed(gestures,L(),target);keyboard.FlushForTest();check(fires==1,"Held keyboard modifiers cancel accidental shape recognition");keyboard.Handle(new Native.Keyboard{vk=162,flags=128});
    var scoped=binding.Copy();scoped.Id="scoped";scoped.Name="App L";scoped.AppPath=System.Reflection.Assembly.GetExecutingAssembly().Location;state.Bindings.Add(scoped);gestures.Refresh();Feed(gestures,L(),target);keyboard.FlushForTest();check(fires==2&&selected=="App L","App-specific identical shape takes precedence over global shape");state.Bindings.Remove(scoped);
    var work=binding.Copy();work.Id="work";work.ProfileId="work";work.Name="Work L";state.Bindings.Add(work);gestures.Refresh();Feed(gestures,L(),target);keyboard.FlushForTest();check(fires==3&&selected=="Work L","Profile-specific shape takes precedence over a shared identical shape");state.Bindings.Remove(work);gestures.Refresh();
    int recorded=0;gestures.Recorded+=points=>recorded=points.Count;gestures.BeginRecording();Feed(gestures,L(),target);check(recorded>=8&&!gestures.Busy,"Touchpad recording finishes on pause without a button press");
    var dialog=new GestureWindow(gestures,keyboard,state,()=>new SystemShortcut[0]){Owner=owner};dialog.Show();try{dialog.RecordForTest(Circle());dialog.ActionForTest(binding);var result=dialog.DraftForTest();check(result.Gesture.Points.Count>=8&&result.Key==0&&result.Kind=="Send key"&&result.SendKey==67,"Gesture editor binds a recorded shape to an existing action");check(dialog.SaveVisibleForTest,"Shape editor exposes the actual Save button");screenshot(dialog,"touchpad-editor-preview.png");dialog.Hide();Application.Current.Dispatcher.BeginInvoke(new Action(()=>dialog.SaveForTest()));check(dialog.ShowDialog()==true&&dialog.Result.Gesture!=null,"Shape editor saves through its visible Save button");}finally{dialog.Close();}
   }
   using(var keyboard=new KeyboardEngine()){keyboard.AllowOwnPointerForTest=true;var wheel=new Binding{Name="Fine wheel",Key=InputKeys.WheelUp};keyboard.Bindings=()=>new List<Binding>{wheel};int fires=0;keyboard.Fire=(b,w)=>fires++;for(int i=0;i<119;i++)keyboard.MouseForTest(0x20A,new Native.MouseEvent{Data=1u<<16});keyboard.FlushForTest();check(fires==0,"High-resolution wheel packets are accumulated rather than over-triggered");keyboard.MouseForTest(0x20A,new Native.MouseEvent{Data=1u<<16});keyboard.FlushForTest();check(fires==1,"120 small wheel deltas produce one shortcut");
    wheel.Key=119;keyboard.AllowRemappedInput=true;keyboard.Handle(new Native.Keyboard{vk=119,flags=16});keyboard.Handle(new Native.Keyboard{vk=119,flags=16|128});keyboard.FlushForTest();check(fires==2,"Optional device-utility keyboard remaps are accepted");keyboard.Handle(new Native.Keyboard{vk=119,flags=16,extra=new UIntPtr(0x414B534D)});keyboard.Handle(new Native.Keyboard{vk=119,flags=16|128,extra=new UIntPtr(0x414B534D)});keyboard.FlushForTest();check(fires==2,"Makro+ output never loops even when software remaps are accepted");
    keyboard.AllowRemappedInput=false;keyboard.Handle(new Native.Keyboard{vk=119});keyboard.ExpireForTest();keyboard.Handle(new Native.Keyboard{vk=119});keyboard.Handle(new Native.Keyboard{vk=119,flags=128});keyboard.FlushForTest();check(fires==3,"Lost key-up after a disconnected device recovers after timeout");
   }
   var devices=RawPointerSource.Devices();check(devices.All(d=>!string.IsNullOrEmpty(d.Id)&&!string.IsNullOrEmpty(d.Type)),"Windows input device inventory can be read without altering drivers");owner.ProductViewForTest("Home");
  }
 }
}
